 ArrayList<C> parse(String s,String base){ArrayList<C>o=new ArrayList<>();String n=null,l="",g="ทั่วไป",id="";for(String raw:s.replace("\uFEFF","").replace("\r","").split("\\n")){String x=raw.trim();if(x.isEmpty())continue;if(x.regionMatches(true,0,"#EXTINF",0,7)){int k=x.indexOf(',');String inf=k>0?x.substring(0,k):x;n=k>0?x.substring(k+1).trim():"ช่อง";l=at(inf,"tvg-logo");g=at(inf,"group-title");id=at(inf,"tvg-id");if(g.isEmpty())g="ทั่วไป";}else if(n!=null&&!x.startsWith("#")){o.add(new C(n,resolve(base,x),l,g,id));n=null;}else if(!x.startsWith("#")&&(x.startsWith("http://")||x.startsWith("https://")))o.add(new C(x,x,"","ทั่วไป",""));}return o;}
