 void playFiles(){try{LinkedHashMap<String,F>a=new LinkedHashMap<>();Uri base=MediaStore.Files.getContentUri("external");String s=MediaStore.MediaColumns.DISPLAY_NAME+" LIKE ? OR "+MediaStore.MediaColumns.DISPLAY_NAME+" LIKE ? OR "+MediaStore.MediaColumns.DISPLAY_NAME+" LIKE ?";String[]q={"%.m3u","%.M3U","%.m3u8"};try(Cursor c=getContentResolver().query(base,new String[]{MediaStore.MediaColumns._ID,MediaStore.MediaColumns.DISPLAY_NAME},s,q,MediaStore.MediaColumns.DATE_ADDED+" DESC")){if(c!=null)while(c.moveToNext()){long id=c.getLong(0);a.put(String.valueOf(id),new F(c.getString(1),ContentUris.withAppendedId(base,id)));}}for(String x:pref.getString("files","").split("\\n")){int p=x.indexOf('|');if(p>0)a.put(x.substring(0,p),new F(x.substring(p+1),Uri.parse(x.substring(0,p))));}playlists.clear();playlists.addAll(a.values());}catch(Exception e){}}
